// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {TimelockController} from "../src/TimelockController.sol";

contract InvMutTest is Test {
    TimelockController c;

    function setUp() public { c = new TimelockController(0, new address[](0), new address[](0)); }

    function testFuzz_property(address caller, address account) public {
        vm.assume(caller != account);
        vm.assume(account != address(0));
        vm.assume(caller != address(this));

        bytes32 role = c.PROPOSER_ROLE();

        // grant the role to `account` (the test contract holds TIMELOCK_ADMIN_ROLE as deployer)
        c.grantRole(role, account);
        assertTrue(c.hasRole(role, account), "setup: account should hold role");

        // a third party attempts to renounce the role on behalf of `account`
        vm.prank(caller);
        try c.renounceRole(role, account) {
            // even if the call succeeds, the third party must not have revoked someone else's role
            assertTrue(c.hasRole(role, account), "third party must not renounce another account's role");
        } catch {
            // reference reverts: membership untouched
            assertTrue(c.hasRole(role, account), "role must remain after failed renounce attempt");
        }
    }
}
